"use client";

import { useState } from "react";
import { ArrowDown, ArrowUp, Plus, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { adminUpload } from "./admin-fetch";
import { isProductImageTooSmall } from "@/lib/product-image";

export function MediaField({
  label,
  urls,
  onChange,
  accept = "image/*",
  hint,
}: {
  label: string;
  urls: string[];
  onChange: (urls: string[]) => void;
  accept?: string;
  hint?: string;
}) {
  const [paste, setPaste] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [warn, setWarn] = useState<string | null>(null);

  async function onFile(file?: File) {
    if (!file) return;
    setBusy(true);
    setError(null);
    setWarn(null);
    try {
      const json = await adminUpload(file);
      onChange([...urls, json.secureUrl]);
      if (accept.startsWith("image") && isProductImageTooSmall(json.width, json.height)) {
        setWarn(
          "This photo is smaller than 800 ├ù 800. It may look blurry. Use a square 2048 ├ù 2048 photo for a sharp result."
        );
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setBusy(false);
    }
  }

  function addPaste() {
    const url = paste.trim();
    if (!url) return;
    onChange([...urls, url]);
    setPaste("");
  }

  function move(index: number, dir: -1 | 1) {
    const next = [...urls];
    const target = index + dir;
    if (target < 0 || target >= next.length) return;
    [next[index], next[target]] = [next[target], next[index]];
    onChange(next);
  }

  return (
    <div className="space-y-3">
      <Label>{label}</Label>
      {hint ? <p className="text-sm text-muted-foreground">{hint}</p> : null}
      <div className="space-y-2">
        {urls.map((url, i) => (
          <div key={`${url}-${i}`} className="flex items-center gap-2">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            {accept.startsWith("image") ? (
              <img src={url} alt="" className="h-12 w-12 rounded object-cover" />
            ) : null}
            <p className="min-w-0 flex-1 truncate text-xs text-muted-foreground">{url}</p>
            <Button type="button" variant="ghost" size="icon" aria-label="Move up" onClick={() => move(i, -1)}>
              <ArrowUp className="h-4 w-4" />
            </Button>
            <Button type="button" variant="ghost" size="icon" aria-label="Move down" onClick={() => move(i, 1)}>
              <ArrowDown className="h-4 w-4" />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              aria-label="Remove"
              onClick={() => onChange(urls.filter((_, j) => j !== i))}
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        ))}
      </div>
      <div className="flex flex-col gap-2 sm:flex-row">
        <Input
          type="file"
          accept={accept}
          disabled={busy}
          onChange={(e) => onFile(e.target.files?.[0])}
        />
        <div className="flex flex-1 gap-2">
          <Input
            placeholder="Paste URL"
            value={paste}
            onChange={(e) => setPaste(e.target.value)}
          />
          <Button type="button" variant="outline" onClick={addPaste}>
            <Plus className="mr-1 h-4 w-4" />
            Add
          </Button>
        </div>
      </div>
      {warn ? <p className="text-sm text-amber-700">{warn}</p> : null}
      {error ? <p className="text-sm text-destructive">{error}</p> : null}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import { Plus } from "lucide-react";

import { Button } from "@/components/ui/button";
import { fetchStoreProducts } from "@/lib/store-client";
import { imageUrl } from "@/lib/sanity/image";
import { getDefaultVariant, getStockState } from "@/lib/stock";
import type { Product } from "@/lib/types";
import { useCart } from "@/components/cart/cart-provider";
import { formatPrice } from "@/lib/utils";

export function CartUpsell({ excludeSlugs }: { excludeSlugs: string[] }) {
  const [products, setProducts] = useState<Product[]>([]);
  const { addItem } = useCart();

  useEffect(() => {
    fetchStoreProducts()
      .then((all) => {
        const addable = (p: Product) => {
          if (p.stockStatus === "out-of-stock") return false;
          const v = getDefaultVariant(p);
          return v ? getStockState(v.stockStatus).purchasable : !(p.variants?.length);
        };
        const suggestions = all
          .filter((p) => !excludeSlugs.includes(p.slug) && addable(p))
          .sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))
          .slice(0, 3);
        setProducts(suggestions);
      })
      .catch(() => {});
  }, [excludeSlugs.join(",")]);

  if (products.length === 0) return null;

  return (
    <div className="border-t pt-4">
      <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        You might also like
      </p>
      <div className="space-y-3">
        {products.map((p) => {
          const img = p.images?.[0];
          return (
            <div key={p._id} className="flex items-center gap-3">
              {img ? (
                <div className="relative h-12 w-12 shrink-0 overflow-hidden rounded-lg bg-muted">
                  <Image
                    src={imageUrl(img, { w: 96 })}
                    alt={p.name}
                    fill
                    sizes="48px"
                    className="object-cover"
                  />
                </div>
              ) : (
                <div className="h-12 w-12 shrink-0 rounded-lg bg-muted" />
              )}
              <div className="min-w-0 flex-1">
                <p className="line-clamp-1 text-xs font-medium">{p.name}</p>
                <p className="text-xs font-semibold">{formatPrice(p.price)}</p>
              </div>
              <Button
                size="icon"
                variant="outline"
                className="h-8 w-8 shrink-0"
                aria-label={`Add ${p.name} to cart`}
                onClick={() => {
                  const v = getDefaultVariant(p);
                  addItem({
                    slug: p.slug,
                    name: p.name,
                    price: v?.price ?? p.price,
                    image: img ? imageUrl(img, { w: 128 }) : undefined,
                    productId: p._id,
                    ...(v
                      ? {
                          variantKey: v._key,
                          variantId: v._key,
                          variantName: v.name,
                          ...(v.sku ? { variantSku: v.sku } : {}),
                        }
                      : {}),
                  });
                }}
              >
                <Plus className="h-3.5 w-3.5" />
              </Button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "motion/react";
import { ShoppingBag, Zap, Check } from "lucide-react";
import { triggerCartParticleBurst } from "@/components/effects/anime-burst";

interface FloatingCartBarProps {
  productName: string;
  price: number;
  imageUrl?: string;
  visible: boolean;
  onAddToCart?: () => void;
  onBuyNow?: () => void;
}

export function FloatingAddToCartBar({
  productName,
  price,
  imageUrl,
  visible,
  onAddToCart,
  onBuyNow,
}: FloatingCartBarProps) {
  const [added, setAdded] = useState(false);

  const handleAdd = (e: React.MouseEvent<HTMLButtonElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    triggerCartParticleBurst(rect.left + rect.width / 2, rect.top + rect.height / 2);
    setAdded(true);
    onAddToCart?.();
    setTimeout(() => setAdded(false), 2000);
  };

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          initial={{ y: 80, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 80, opacity: 0 }}
          transition={{ type: "spring", stiffness: 320, damping: 28 }}
          className="fixed bottom-6 inset-x-0 z-40 mx-auto max-w-3xl px-4"
        >
          <div className="flex items-center justify-between gap-4 rounded-2xl border border-border/80 bg-background/90 p-3 shadow-2xl backdrop-blur-xl ring-1 ring-black/5 dark:ring-white/10">
            <div className="flex items-center gap-3 min-w-0">
              {imageUrl && (
                <img
                  src={imageUrl}
                  alt={productName}
                  className="h-11 w-11 rounded-xl object-cover bg-muted border border-border p-0.5 shrink-0"
                />
              )}
              <div className="truncate">
                <p className="text-sm font-bold text-foreground truncate">{productName}</p>
                <p className="text-xs font-mono font-semibold text-primary">Rs. {price.toLocaleString()}</p>
              </div>
            </div>

            <div className="flex items-center gap-2 shrink-0">
              <button
                type="button"
                onClick={handleAdd}
                className="relative inline-flex items-center gap-1.5 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold tracking-wide text-primary-foreground shadow-sm transition-all hover:bg-primary-hover active:scale-95"
              >
                {added ? <Check className="w-4 h-4" /> : <ShoppingBag className="w-4 h-4" />}
                <span>{added ? "Added" : "Add to Cart"}</span>
              </button>

              <button
                type="button"
                onClick={onBuyNow}
                className="inline-flex items-center gap-1.5 rounded-lg bg-foreground px-4 py-2.5 text-sm font-semibold tracking-wide text-background shadow-sm transition-all hover:bg-foreground/90 active:scale-95"
              >
                <Zap className="w-4 h-4 fill-current" />
                <span>Buy Now</span>
              </button>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import Image from "next/image";
import { ShoppingCart, Check, Plus } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { fetchStoreProducts } from "@/lib/store-client";
import { imageUrl } from "@/lib/sanity/image";
import { getDefaultVariant, getStockState } from "@/lib/stock";
import type { Product } from "@/lib/types";
import { cn, formatPrice } from "@/lib/utils";
import { useCart } from "@/components/cart/cart-provider";

interface BundleItem {
  product: Product;
  selected: boolean;
}

/**
 * "Complete Your Setup" ÔÇö same-category / compatible pairing suggestions
 * driven by real category data. No purchase-history wording ("Frequently
 * Bought Together"), no invented bundle discounts or savings.
 */
export function FrequentlyBoughtTogether({ current }: { current: Product }) {
  const [items, setItems] = useState<BundleItem[]>([]);
  const { addItem } = useCart();

  useEffect(() => {
    fetchStoreProducts()
      .then((products) => {
        const addable = (p: Product) => {
          if (p.stockStatus === "out-of-stock") return false;
          const v = getDefaultVariant(p);
          return v ? getStockState(v.stockStatus).purchasable : !(p.variants?.length);
        };
        const sameCategory = products
          .filter((p) => p._id !== current._id && p.category === current.category && addable(p))
          .slice(0, 2);
        const crossCategory = products
          .filter((p) => p._id !== current._id && p.category !== current.category && addable(p))
          .slice(0, 2);
        const suggestions = [...sameCategory, ...crossCategory].slice(0, 3);
        setItems(suggestions.map((p) => ({ product: p, selected: true })));
      })
      .catch(() => {});
  }, [current._id]);

  const currentLine = useMemo(() => {
    const v = getDefaultVariant(current);
    if (v) {
      return {
        slug: current.slug,
        name: current.name,
        price: v.price ?? current.price,
        image: current.images?.[0] ? imageUrl(current.images[0], { w: 128 }) : undefined,
        productId: current._id,
        variantKey: v._key,
        variantId: v._key,
        variantName: v.name,
        ...(v.sku ? { variantSku: v.sku } : {}),
      };
    }
    if ((current.variants?.length ?? 0) > 0) return null;
    return {
      slug: current.slug,
      name: current.name,
      price: current.price,
      image: current.images?.[0] ? imageUrl(current.images[0], { w: 128 }) : undefined,
      productId: current._id,
    };
  }, [current]);

  const bundlePrice = useMemo(() => {
    const base = currentLine?.price ?? 0;
    const extras = items
      .filter((i) => i.selected)
      .reduce((sum, i) => {
        const v = getDefaultVariant(i.product);
        return sum + (v?.price ?? i.product.price);
      }, 0);
    return base + extras;
  }, [currentLine, items]);

  if (items.length === 0) return null;

  function toggleItem(index: number) {
    setItems((prev) =>
      prev.map((item, i) => (i === index ? { ...item, selected: !item.selected } : item))
    );
  }

  function addBundleToCart() {
    if (!currentLine) return;
    addItem(currentLine);
    items
      .filter((i) => i.selected)
      .forEach((i) => {
        const v = getDefaultVariant(i.product);
        addItem({
          slug: i.product.slug,
          name: i.product.name,
          price: v?.price ?? i.product.price,
          image: i.product.images?.[0] ? imageUrl(i.product.images[0], { w: 128 }) : undefined,
          productId: i.product._id,
          ...(v
            ? {
                variantKey: v._key,
                variantId: v._key,
                variantName: v.name,
                ...(v.sku ? { variantSku: v.sku } : {}),
              }
            : {}),
        });
      });
  }

  return (
    <section className="mt-16" aria-labelledby="complete-your-setup">
      <h2 id="complete-your-setup" className="text-2xl font-bold tracking-tight">
        Complete Your Setup
      </h2>
      <p className="mt-1 text-sm text-muted-foreground">
        Products that pair naturally with {current.name} ÔÇö all in stock.
      </p>

      <div className="mt-6 grid gap-4 lg:grid-cols-[1fr_auto_1fr]">
        {/* Current product */}
        <Card className="flex items-center gap-4 p-4">
          <div className="relative h-20 w-20 shrink-0 overflow-hidden rounded-lg bg-muted">
            {current.images?.[0] && (
              <Image
                src={imageUrl(current.images[0], { w: 160 })}
                alt={current.name}
                fill
                sizes="80px"
                className="object-cover"
              />
            )}
          </div>
          <div className="min-w-0 flex-1">
            <p className="line-clamp-2 text-sm font-medium">{current.name}</p>
            <p className="mt-1 font-semibold">
              {formatPrice(currentLine?.price ?? current.price)}
            </p>
          </div>
          {currentLine && <Check className="h-5 w-5 shrink-0 text-primary" />}
        </Card>

        {/* Suggested items */}
        <div className="flex flex-col gap-3">
          {items.map((item, index) => (
            <Card
              key={item.product._id}
              className={cn(
                "flex items-center gap-3 p-3 transition-all",
                item.selected ? "border-primary/50 bg-primary/5" : "opacity-50"
              )}
            >
              <button
                onClick={() => toggleItem(index)}
                className={cn(
                  "flex h-5 w-5 shrink-0 items-center justify-center rounded border transition-colors",
                  item.selected
                    ? "border-primary bg-primary text-primary-foreground"
                    : "border-border"
                )}
                aria-label={`Toggle ${item.product.name}`}
              >
                {item.selected && <Check className="h-3 w-3" />}
              </button>
              <div className="relative h-14 w-14 shrink-0 overflow-hidden rounded-lg bg-muted">
                {item.product.images?.[0] && (
                  <Image
                    src={imageUrl(item.product.images[0], { w: 120 })}
                    alt={item.product.name}
                    fill
                    sizes="56px"
                    className="object-cover"
                  />
                )}
              </div>
              <div className="min-w-0 flex-1">
                <p className="line-clamp-1 text-xs font-medium">{item.product.name}</p>
                <p className="text-xs font-semibold">{formatPrice(item.product.price)}</p>
              </div>
            </Card>
          ))}
        </div>

        {/* Summary */}
        <Card className="flex flex-col items-center justify-center gap-3 p-6 text-center">
          <div>
            <p className="text-sm text-muted-foreground">Combined Price</p>
            <p className="mt-1 text-2xl font-bold">{formatPrice(bundlePrice)}</p>
          </div>
          <Button
            className="w-full gap-2"
            onClick={addBundleToCart}
            disabled={!currentLine}
            title={currentLine ? undefined : "Choose an option for this product first"}
          >
            <ShoppingCart className="h-4 w-4" />
            {currentLine ? "Add All to Cart" : "Options Required"}
          </Button>
          <p className="flex items-center gap-1 text-xs text-muted-foreground">
            <Plus className="h-3 w-3" />
            {items.filter((i) => i.selected).length + 1} items
          </p>
        </Card>
      </div>
    </section>
  );
}

"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import Link from "next/link";
import { X, BarChart3 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { StarRating } from "@/components/product/star-rating";
import { fetchStoreProducts } from "@/lib/store-client";
import { imageUrl } from "@/lib/sanity/image";
import type { Product } from "@/lib/types";
import { cn, formatPrice } from "@/lib/utils";

const STORAGE_KEY = "voltgear-compare";
const MAX_COMPARE = 3;

export function useCompare() {
  const [slugs, setSlugs] = useState<string[]>([]);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) setSlugs(JSON.parse(raw));
    } catch {}
  }, []);

  useEffect(() => {
    if (slugs.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(slugs));
    } else if (typeof window !== "undefined") {
      localStorage.removeItem(STORAGE_KEY);
    }
  }, [slugs]);

  function toggle(slug: string) {
    setSlugs((prev) => {
      if (prev.includes(slug)) return prev.filter((s) => s !== slug);
      if (prev.length >= MAX_COMPARE) return prev;
      return [...prev, slug];
    });
  }

  function clear() {
    setSlugs([]);
    localStorage.removeItem(STORAGE_KEY);
  }

  function remove(slug: string) {
    setSlugs((prev) => prev.filter((s) => s !== slug));
  }

  return { slugs, count: slugs.length, toggle, clear, remove };
}

export function CompareBar({
  slugs,
  onClear,
  onRemove,
}: {
  slugs: string[];
  onClear: () => void;
  onRemove: (slug: string) => void;
}) {
  const [products, setProducts] = useState<Product[]>([]);

  useEffect(() => {
    if (slugs.length === 0) { setProducts([]); return; }
    fetchStoreProducts()
      .then((all) => setProducts(all.filter((p) => slugs.includes(p.slug))))
      .catch(() => {});
  }, [slugs.join(",")]);

  if (slugs.length === 0) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-[80] border-t bg-background/95 p-3 shadow-lg backdrop-blur">
      <div className="container mx-auto flex items-center gap-4 lg:px-8">
        <BarChart3 className="h-5 w-5 shrink-0 text-primary" />
        <div className="flex flex-1 items-center gap-2 overflow-x-auto">
          {products.map((p) => (
            <div key={p._id} className="flex shrink-0 items-center gap-2 rounded-full border bg-muted/50 pl-1 pr-2">
              {p.images?.[0] && (
                <div className="relative h-6 w-6 overflow-hidden rounded-full">
                  <Image src={imageUrl(p.images[0], { w: 48 })} alt={p.name} fill sizes="24px" className="object-cover" />
                </div>
              )}
              <span className="max-w-[120px] truncate text-xs font-medium">{p.name}</span>
              <button onClick={() => onRemove(p.slug)} className="text-muted-foreground hover:text-foreground">
                <X className="h-3 w-3" />
              </button>
            </div>
          ))}
        </div>
        <Button asChild size="sm" disabled={slugs.length < 2}>
          <Link href={`/compare?products=${slugs.join(",")}`}>
            Compare ({slugs.length})
          </Link>
        </Button>
        <Button variant="ghost" size="sm" onClick={onClear}>Clear</Button>
      </div>
    </div>
  );
}

export function CompareButton({ slug }: { slug: string }) {
  const [slugs, setSlugs] = useState<string[]>([]);
  const active = slugs.includes(slug);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) setSlugs(JSON.parse(raw));
    } catch {}
  }, []);

  function toggle() {
    setSlugs((prev) => {
      let next: string[];
      if (prev.includes(slug)) {
        next = prev.filter((s) => s !== slug);
      } else if (prev.length >= MAX_COMPARE) {
        return prev;
      } else {
        next = [...prev, slug];
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      window.dispatchEvent(new Event("compare-updated"));
      return next;
    });
  }

  return (
    <button
      onClick={(e) => { e.preventDefault(); e.stopPropagation(); toggle(); }}
      className={cn(
        "absolute bottom-3 right-3 z-10 flex h-9 w-9 items-center justify-center rounded-full shadow-md backdrop-blur transition-all",
        active
          ? "bg-primary text-primary-foreground opacity-100"
          : "bg-background/90 text-foreground opacity-0 group-hover:opacity-100 hover:bg-background"
      )}
      aria-label={active ? "Remove from comparison" : "Add to comparison"}
    >
      <BarChart3 className="h-4 w-4" />
    </button>
  );
}

export function ComparePage() {
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [compareSlugs, setCompareSlugs] = useState<string[]>([]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const productsParam = params.get("products");
    if (productsParam) {
      setCompareSlugs(productsParam.split(",").filter(Boolean));
    }
    fetchStoreProducts()
      .then(setAllProducts)
      .catch(() => {});
  }, []);

  const products = allProducts.filter((p) => compareSlugs.includes(p.slug));

  if (products.length < 2) {
    return (
      <div className="container mx-auto px-4 py-12 text-center lg:px-8">
        <BarChart3 className="mx-auto h-12 w-12 text-muted-foreground" />
        <h1 className="mt-4 text-2xl font-bold">Compare Products</h1>
        <p className="mt-2 text-muted-foreground">
          Select at least 2 products from their cards using the comparison button.
        </p>
        <Button asChild className="mt-6">
          <Link href="/products">Browse Products</Link>
        </Button>
      </div>
    );
  }

  const allSpecLabels = Array.from(
    new Set(products.flatMap((p) => (p.specifications ?? []).map((s) => s.label)))
  );

  return (
    <div className="container mx-auto px-4 py-12 lg:px-8">
      <h1 className="mb-8 text-2xl font-bold">Compare Products</h1>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[600px] border-collapse">
          <thead>
            <tr>
              <th className="w-40 p-3 text-left text-sm font-medium text-muted-foreground">Feature</th>
              {products.map((p) => (
                <th key={p._id} className="p-3 text-center">
                  <div className="mx-auto relative mb-3 h-24 w-24 overflow-hidden rounded-lg bg-muted">
                    {p.images?.[0] && (
                      <Image src={imageUrl(p.images[0], { w: 240 })} alt={p.name} fill sizes="96px" className="object-cover" />
