          {/* Previous / Next Slider Arrow Navigation - Sleek accessories hub styling */}
          {slideCount > 1 && (
            <>
              <button
                type="button"
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  goToPrev();
