import type { HeroSection, Product, StoreImage } from "@/lib/types";

export interface HeroSlide {
  id: string;
  image?: StoreImage | string;
  alt: string;
  headline?: string;
  subheadline?: string;
  primaryCta?: { label?: string; href?: string };
  secondaryCta?: { label?: string; href?: string };
  featuredProduct?: Product;
}

import { getFallbackHeroImages } from "@/lib/fallback-images";

export function getHeroSlides(
  realHero: HeroSection | null,
  products: Product[] = []
): HeroSlide[] {
  const slides: HeroSlide[] = [];

  const realImages = realHero?.backgroundImages?.length
    ? realHero.backgroundImages
    : realHero?.backgroundImage
    ? [realHero.backgroundImage]
    : getFallbackHeroImages();

  const hasRealImages = realImages.length > 0;

  if (hasRealImages) {
    // We have images, either real or fallback
    const baseHero = realHero || {
      headline: "Power Your Everyday.",
      subheadline: "Premium electronics accessories designed for performance.",
      primaryCta: { label: "Shop Products", href: "/products" },
    };

    realImages.forEach((img, index) => {
      slides.push({
        id: `hero-slide-${index}`,
        image: img,
        headline: index === 0 ? baseHero.headline : undefined,
        subheadline: index === 0 ? baseHero.subheadline : undefined,
        primaryCta: baseHero.primaryCta,
        secondaryCta: index === 0 ? (baseHero as any).secondaryCta : undefined,
        featuredProduct: index === 0 ? (baseHero as any).featuredProduct : undefined,
        alt: `${baseHero.headline || "Hero Slide"} ${index + 1}`,
      });
    });
  } else if (realHero) {
    // Real hero without background images (text/featured product layout)
    slides.push({
      id: "real-hero-main",
      headline: realHero.headline,
      subheadline: realHero.subheadline,
      primaryCta: realHero.primaryCta,
      secondaryCta: realHero.secondaryCta,
      featuredProduct: realHero.featuredProduct,
      alt: realHero.headline || "VoltGear Hero",
    });
  }

  // Development/Local visual slider test mode ONLY:
  // If no admin images exist and we are in non-production, append safe demo slides
  if (!hasRealImages && process.env.NODE_ENV !== "production" && slides.length < 2) {
    const productsWithImages = products.filter(
      (p) => p.images?.[0] || p.cloudinaryImages?.[0]
    );

    productsWithImages.slice(0, 3).forEach((prod, index) => {
      const img = prod.images?.[0] || prod.cloudinaryImages?.[0];
      const slideId = `demo-slide-${prod._id || index}`;

      if (img && (!slides[0]?.image || slides[0].image !== img)) {
        slides.push({
          id: slideId,
          image: img,
          headline: prod.name,
          subheadline: prod.shortDescription || `Discover top-tier performance with ${prod.name}.`,
          primaryCta: { label: "Shop Now", href: `/product/${prod.slug}` },
          secondaryCta: { label: "Explore Category", href: `/products/${prod.category}` },
          featuredProduct: prod,
          alt: prod.name,
        });
      }
    });
  }

  // Fallback if no slides exist at all
  if (slides.length === 0) {
    slides.push({
      id: "default-fallback-slide",
      headline: "Power Your Everyday.",
      subheadline: "Premium smartwatches, power banks, chargers and earbuds ÔÇö engineered for people on the move.",
      primaryCta: { label: "Shop Products", href: "/products" },
      alt: "Power Your Everyday",
    });
  }

  return slides;
}

export type ThemeName = "dark" | "light";

/** localStorage key for the visitor's persisted theme choice. */
export const THEME_STORAGE_KEY = "voltage-theme";

const HEX_RE = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i;

export function isHexColor(value: string | undefined | null): value is string {
  return typeof value === "string" && HEX_RE.test(value.trim());
}

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.trim().replace("#", "");
  if (h.length === 3) {
    h = h
      .split("")
      .map((c) => c + c)
      .join("");
  }
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgbToHsl([r, g, b]: [number, number, number]): {
  h: number;
  s: number;
  l: number;
} {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r:
        h = (g - b) / d + (g < b ? 6 : 0);
        break;
      case g:
        h = (b - r) / d + 2;
        break;
      default:
        h = (r - g) / d + 4;
    }
    h /= 6;
  }

  return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}

/** Returns a `h s% l%` triple for use in CSS variables like `--primary`. */
export function hexToHslTriple(hex: string | undefined | null): string | null {
  if (!isHexColor(hex)) return null;
  const { h, s, l } = rgbToHsl(hexToRgb(hex));
  return `${h} ${s}% ${l}%`;
}

/**
 * Picks a foreground color (white or near-black) that stays readable
 * on top of the given background color.
 */
export function foregroundFor(hex: string | undefined | null): string {
  if (!isHexColor(hex)) return "0 0% 100%";
  const [r, g, b] = hexToRgb(hex);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.62 ? "240 6% 10%" : "0 0% 100%";
}

export interface ThemeSettings {
  theme?: string;
  primaryColor?: string;
  secondaryColor?: string;
}

export function resolveTheme(
  settings: ThemeSettings | null,
  previewOverride?: string | null
): ThemeName {
  if (previewOverride === "dark" || previewOverride === "light") {
    return previewOverride;
  }
  return settings?.theme === "dark" ? "dark" : "light";
}

/**
 * Builds CSS custom-property overrides from the CMS brand colors.
 * Returns a string safe to inline in a <style> tag.
 */
export function themeCssVars(_settings: ThemeSettings | null): string {
  // OVERRIDE: Prevent Sanity CMS colors from corrupting the luxury Golden theme.
  // By returning an empty string, the meticulously designed CSS variables in globals.css
  // become the absolute single source of truth for the entire site.
  return "";
}

/**
 * Inline script for <head> that applies the right theme before first paint,
 * so pages never flash. Resolution order: `?theme=dark|light` (preview/demo)
 * ÔåÆ persisted visitor choice (localStorage) ÔåÆ server default from Sanity.
 */
export function themePreviewScript(): string {
  return [
    'try{',
    'var p=new URLSearchParams(window.location.search).get("theme");',
    'var s=null;try{s=localStorage.getItem("voltage-theme")}catch(e){}',
    'var t=(p==="dark"||p==="light")?p:(s==="dark"||s==="light"?s:null);',
    'if(t==="dark"){document.documentElement.classList.add("dark")}',
    'else if(t==="light"){document.documentElement.classList.remove("dark")}',
    "}catch(e){}",
  ].join("");
}
